package app.space.notes.runtime;

import android.content.*;
import android.os.*;
import org.json.JSONObject;
import java.io.*;
import java.util.concurrent.*;

/** Opt-in, app-private, bounded diagnostic breadcrumbs. Never passes note/media/URI content. */
public final class Diagnostics {
 private static final Object LOCK=new Object();
 private static final ThreadPoolExecutor WRITER=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(256),r->{Thread t=new Thread(r,"notes-diagnostics");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static final ThreadPoolExecutor EXPORTER=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"notes-diagnostic-export");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static volatile Context app;private static volatile boolean enabled;private static long generation;private static boolean installed;
 private static final int LIMIT=1024*1024;
 private static final java.util.Set<String> SAFE_CONTROLS=new java.util.HashSet<>(java.util.Arrays.asList("Group shapes","Diagram options","Add item","Move item up","Move item down","Indent item","Outdent item","Remove item","Convert to text","Image","Drawing","Save drawing","Drawing options","Ink colour","Stroke width","Fit paper","Grid lines","Copy drawing as image","Delete drawing","Clear canvas","Drawing help","Pen","Pencil","Highlighter","Eraser","Line","Rectangle","Oval","System","Light","Dark","Add to note","Remove image","Folders","Move to folder","Create folder","Background","Appearance","Diagnostics","Edit shape","Group","Undo diagram","Redo diagram","Edit arrows","Apply filters","Select all","Select none","+ Text","New text note","Library","Add to your note","Colour, labels & reminder","Note actions","Filter & view","+ Checklist","Filters","Hide filters","Undo","Settings","Back","Pin","Unpin","Capture tools","Organise tools","More actions","Text formatting","Share","Copy","Archive","Unarchive","Trash","Restore","Labels","Colour","Reminder","Clear reminder","Diagram","View diagram","Export PDF","Read image","Record voice","Voice inbox","Bold","Italic","Underline","Strike","Heading 1","Heading 2","Clear","+ Item","↑","↓","←","→","Indent","Outdent","Remove","Hide checked","Show checked","To text","Convert to checklist","Process","Decision","Start / End","Input / Output","Ellipse","Text box","Edit shape","Connect","Delete shape","Wider","Narrower","Taller","Shorter","Undo diagram","Back to note","Play","Stop playback","Export WAV","Retry transcript","Open note","Refresh","Stop and transcribe","Storage","Notes","Manage labels","Home widget","List view","Grid view","Sort: created","Sort: edited","All labels","All labels ✓","Storage & recovery","Offline models & licenses","Export diagnostics","Delete diagnostic logs","Choose folder","Open library","Retry save","Backups","Use device storage","Export backup","Import backup","Confirm merge","Cancel","Save labels","Done","Default","Red","Orange","Yellow","Green","Teal","Blue","Dark blue","Purple","Pink","Brown","Gray"));
 public static String controlName(CharSequence name){String value=name==null?"":name.toString();return SAFE_CONTROLS.contains(value)?value:"content-control";}
 private Diagnostics(){}
 public static void initialize(Context context){synchronized(LOCK){if(app!=context.getApplicationContext()){generation++;WRITER.getQueue().clear();}app=context.getApplicationContext();enabled=app.getSharedPreferences("notes-diagnostics",0).getBoolean("enabled",false);if(!installed){installed=true;Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{crash(error);if(previous!=null)previous.uncaughtException(thread,error);else{android.os.Process.killProcess(android.os.Process.myPid());System.exit(10);}});}}if(enabled)environment("session.start");}
 public static boolean enabled(){return enabled;}
 public static void setEnabled(boolean value){synchronized(LOCK){enabled=value;generation++;WRITER.getQueue().clear();app.getSharedPreferences("notes-diagnostics",0).edit().putBoolean("enabled",value).commit();}if(value)environment("collection.enabled");}
 public static void record(String event,String detail){if(!enabled || app==null)return;final long token; synchronized(LOCK){token=generation;}final long at=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();final String thread=Thread.currentThread().getName();try{WRITER.execute(()->{synchronized(LOCK){if(!enabled || token!=generation)return;try{JSONObject row=new JSONObject().put("at_ms",at).put("elapsed_ms",elapsed).put("event",event).put("level",level(event)).put("detail",detail).put("thread",thread).put("heap_used_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());append(row);}catch(Exception ignored){/* Diagnostics must not break notes. */}}});}catch(RejectedExecutionException full){/* Bounded queue: omit breadcrumb, never block UI. */}}
 private static File file(String name){return new File(app.getFilesDir(),name);}
 private static void append(JSONObject row)throws Exception {File current=file("diagnostics.jsonl");byte[] bytes=(row.toString()+"\n").getBytes("UTF-8");if(bytes.length>32768)return;if(current.length()+bytes.length>LIMIT){File previous=file("diagnostics.previous.jsonl");if(previous.exists() && !previous.delete())return;if(!current.renameTo(previous))return;}try(FileOutputStream out=new FileOutputStream(current,true)){out.write(bytes);}}
 public static void failure(String event,Throwable error){if(!enabled)return;try{StringBuilder trace=new StringBuilder(error.getClass().getName());for(StackTraceElement frame:error.getStackTrace()){if(trace.length()>8000)break;trace.append("\n at ").append(frame);}record(event,trace.toString());}catch(Throwable ignored){}}
 public static void clear(){synchronized(LOCK){generation++;WRITER.getQueue().clear();file("diagnostics.jsonl").delete();file("diagnostics.previous.jsonl").delete();}}
 public static long bytes(){synchronized(LOCK){return file("diagnostics.jsonl").length()+file("diagnostics.previous.jsonl").length();}}
 public static void environment(String reason){if(!enabled)return;try{android.content.res.Configuration c=app.getResources().getConfiguration();android.app.ActivityManager.MemoryInfo memory=new android.app.ActivityManager.MemoryInfo();((android.app.ActivityManager)app.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(memory);JSONObject row=new JSONObject().put("reason",reason).put("sdk",Build.VERSION.SDK_INT).put("release",Build.VERSION.RELEASE).put("manufacturer",Build.MANUFACTURER).put("model",Build.MODEL).put("security_patch",Build.VERSION.SECURITY_PATCH).put("app_package",app.getPackageName()).put("timezone",java.util.TimeZone.getDefault().getID()).put("density_dpi",app.getResources().getDisplayMetrics().densityDpi).put("power_save",((PowerManager)app.getSystemService(Context.POWER_SERVICE)).isPowerSaveMode()).put("abis",java.util.Arrays.toString(Build.SUPPORTED_ABIS)).put("app_version",app.getPackageManager().getPackageInfo(app.getPackageName(),0).versionName).put("version_code",app.getPackageManager().getPackageInfo(app.getPackageName(),0).versionCode).put("font_scale",c.fontScale).put("orientation",c.orientation).put("night",c.uiMode & 48).put("width_dp",c.screenWidthDp).put("height_dp",c.screenHeightDp).put("locale",c.getLocales().toLanguageTags()).put("available_ram_bytes",memory.availMem).put("low_memory",memory.lowMemory).put("free_internal_bytes",app.getFilesDir().getUsableSpace()).put("pss_kib",Debug.getPss()).put("native_heap_bytes",Debug.getNativeHeapAllocatedSize()).put("microphone_granted",app.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==0).put("notifications_enabled",((android.app.NotificationManager)app.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled());record("environment",row.toString());}catch(Exception e){record("environment.failure",e.getClass().getSimpleName());}}
 private static void crash(Throwable error){synchronized(LOCK){if(!enabled || app==null)return;try{StringBuilder trace=new StringBuilder(error.getClass().getName());for(StackTraceElement frame:error.getStackTrace()){if(trace.length()>10000)break;trace.append("\n at ").append(frame);}append(new JSONObject().put("at_ms",System.currentTimeMillis()).put("event","uncaught.java").put("level","ERROR").put("stack_no_messages",trace.toString()));}catch(Throwable ignored){}}}
 public static String level(String event){String value=event.toLowerCase(java.util.Locale.ROOT);return value.contains("fail") || value.contains("uncaught") || value.contains("error")?"ERROR":value.contains("warn")?"WARN":value.startsWith("ui.") || value.contains("phase") || value.startsWith("lifecycle.")?"DEBUG":"INFO";}
 public static final class Snapshot {public final java.util.List<JSONObject> rows;public final int total;Snapshot(java.util.List<JSONObject> rows,int total){this.rows=java.util.Collections.unmodifiableList(rows);this.total=total;}}
 private static Snapshot filtered(long from,long to,java.util.Set<String> levels)throws Exception{
  java.util.List<JSONObject> rows=new java.util.ArrayList<>();
  synchronized(LOCK){for(String name:new String[]{"diagnostics.previous.jsonl","diagnostics.jsonl"}){File source=file(name);if(!source.exists())continue;try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(source),"UTF-8"))){String line;while((line=reader.readLine())!=null){if(line.length()>32768)continue;try{JSONObject row=new JSONObject(line);long at=row.optLong("at_ms",0);String severity=row.optString("level",level(row.optString("event","")));if(at>=from && at<=to && levels.contains(severity))rows.add(row);}catch(org.json.JSONException malformed){/* Keep original file, omit incomplete/corrupt record from parsed view. */}}}}}
  rows.sort((a,b)->Long.compare(b.optLong("at_ms"),a.optLong("at_ms")));int total=rows.size();return new Snapshot(new java.util.ArrayList<>(rows.subList(0,Math.min(5000,total))),total);
 }
 public static void read(long from,long to,java.util.Set<String> levels,java.util.function.Consumer<Snapshot> success,java.util.function.Consumer<Exception> failure){java.util.Set<String> selected=new java.util.HashSet<>(levels);try{WRITER.execute(()->{try{success.accept(filtered(from,to,selected));}catch(Exception | OutOfMemoryError error){failure.accept(error instanceof Exception?(Exception)error:new IOException("Not enough memory to read logs"));}});}catch(RejectedExecutionException full){failure.accept(full);}}
 private static void requireLocalDestination(Context context,android.net.Uri uri)throws Exception{if("file".equals(uri.getScheme())){String path=new File(uri.getPath()).getCanonicalPath();if(!path.startsWith(context.getFilesDir().getCanonicalPath()+File.separator) && !path.startsWith(context.getCacheDir().getCanonicalPath()+File.separator))throw new IOException("Choose an app-private or on-device destination");}else LocalDeviceDocuments.requireReadable(uri);}
 public static void exportFiltered(Context context,android.net.Uri uri,long from,long to,java.util.Set<String> levels,Runnable success,java.util.function.Consumer<Exception> failure){
  read(from,to,levels,snapshot->{try{requireLocalDestination(context,uri);}catch(Exception invalid){failure.accept(invalid);return;}StringBuilder text=new StringBuilder("MyNotes filtered diagnostics — newest first; at most 5,000 records. Local app events only; no note/media contents. Review before sharing.\n");for(JSONObject row:snapshot.rows)text.append(row).append('\n');try{EXPORTER.execute(()->{try{try(OutputStream output=context.getContentResolver().openOutputStream(uri,"wt")){if(output==null)throw new IOException("Cannot open destination");output.write(text.toString().getBytes("UTF-8"));}success.run();}catch(Exception | OutOfMemoryError error){failure.accept(error instanceof Exception?(Exception)error:new IOException("Not enough memory to export logs"));}});}catch(RejectedExecutionException full){failure.accept(full);}},failure);
 }
 /** Snapshot is ordered behind prior breadcrumbs; caller streams off the UI thread. */
 public static void export(Context context,android.net.Uri uri,Runnable success,java.util.function.Consumer<Exception> failure){try{WRITER.execute(()->{
  try{requireLocalDestination(context,uri);ByteArrayOutputStream snapshot=new ByteArrayOutputStream();snapshot.write("MyNotes diagnostics v1 — app events only; no note bodies/audio/images/URI paths. Device context may identify your phone.\n".getBytes("UTF-8"));
   synchronized(LOCK){for(String name:new String[]{"diagnostics.previous.jsonl","diagnostics.jsonl"}){File f=file(name);if(f.exists())try(InputStream in=new FileInputStream(f)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)snapshot.write(buffer,0,n);}}}
   byte[] bytes=snapshot.toByteArray();EXPORTER.execute(()->{try{try(OutputStream out=context.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open destination");out.write(bytes);}success.run();}catch(Exception e){failure.accept(e);}});
  }catch(Exception e){failure.accept(e);}
 });}catch(RejectedExecutionException full){failure.accept(full);}}
}
